import "dart:convert";

import "package:cradock_map/models/commune_boundary.dart";
import "package:flutter/foundation.dart";
import "package:flutter/services.dart";

class CommuneBoundaryData {
  /// Generated by tool/fetch_communes.py (IGN ADMIN EXPRESS COG).
  static const String assetPath = "assets/data/communes.geojson";
  static const String attribution = "IGN – ADMIN EXPRESS COG 2026";

  static Future<List<CommuneBoundary>> load() async {
    final content = await rootBundle.loadString(assetPath);
    // In a background isolate on mobile/desktop (inline on the web).
    return compute(parse, content, debugLabel: "parse communes");
  }

  static List<CommuneBoundary> parse(String geoJson) {
    final collection = jsonDecode(geoJson) as Map<String, dynamic>;
    return [
      for (var feature in collection["features"] as List)
        CommuneBoundary.fromGeoJson(feature as Map<String, dynamic>)
    ];
  }
}
